    "theme": "Le plus beau des récits : l'histoire complète de Joseph — le songe, le puits, la tentation, la prison, l'interprétation des rêves, l'élévation en Égypte et le pardon aux frères — une seule narration continue sur la fidélité de Dieu envers les patients",
