      "ar": "قَالُواْ جَزَـٰؤُهُ مَن وُجِدَ فِي رَحْلِهِ فَهُوَ جَزَـٰؤُهُ كَذَٰلِكَ نَجْزِي الظَّـٰلِمِينَ",
