        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Allah tarafından, onları kuşatacak bir azaba uğramalarından veya farkına varmadan, kıyamet saatinin ansızın gelmesinden güvende midirler"
        }
