    "declic_frequence": "ṣabara (patienter, racine ص-ب-ر) traverse le récit sous sa plus belle forme : ṣabrun jamīl — « une patience belle » (v.18, v.83), celle de Jacob pleurant Joseph sans se plaindre aux créatures. Et Joseph lui-même livre la clé du dénouement (v.90) : innahu man yattaqi wa-yaṣbir — « quiconque craint Dieu et patiente... Allah ne laisse pas perdre la récompense des bienfaisants ». Le ṣabr n'est pas résignation passive : c'est la fidélité maintenue dans l'épreuve — au fond du puits, dans la séduction, en prison — jusqu'à ce que Dieu retourne la situation."
